#if UNITY_STANDALONE_WIN && !UNITY_EDITOR
using System.Collections;
using System.IO;
using UnityEngine;
public class ReferenceCapture:MonoBehaviour {
    string folder;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Init(){var a=System.Environment.GetCommandLineArgs();for(int i=0;i<a.Length-1;i++)if(a[i]=="--reference-capture"){var go=new GameObject("ReferenceCapture");go.AddComponent<ReferenceCapture>().folder=a[i+1];}}
    IEnumerator Start(){Directory.CreateDirectory(folder);yield return new WaitForSecondsRealtime(2);var g=ReferenceGame.Instance;g.LoadLevel(0);g.ShowHome();yield return Shot("01-home");g.StartPlay();yield return Shot("02-first-level");
        foreach(int index in new[]{2,3,7,11,15,22,23,25,28,29}){g.LoadLevel(index);g.StartPlay();yield return new WaitForSecondsRealtime(.1f);yield return Shot("level-"+(index+1));}
        g.LoadLevel(20);g.StartPlay();g.TriggerBombForTest();yield return new WaitForSecondsRealtime(.6f);yield return Shot("03-bomb-failure");
        g.LoadLevel(0);g.StartPlay();g.TestInput=true;g.BeginStick(new Vector2(270,200));g.MoveStick(new Vector2(310,245));g.TestDirection=g.Stick.Value;yield return new WaitForSecondsRealtime(.3f);yield return Shot("04-joystick");g.TestDirection=Vector2.zero;g.LoadLevel(0);g.StartPlay();for(int frame=0;frame<1000&&g.GrowthPoints<10;frame++){g.MoveHoleForTest(g.NearestCollectible());yield return null;}yield return Shot("05-growth");g.LoadLevel(15);g.StartPlay();yield return new WaitForSecondsRealtime(1);var times=new System.Collections.Generic.List<float>();for(int i=0;i<180;i++){yield return null;times.Add(Time.unscaledDeltaTime*1000);}times.Sort();File.WriteAllText(Path.Combine(folder,"DesktopFrameTimes.txt"),"Windows standalone, D3D11, 540x960, stage 16, stationary, 180 frame samples. Not an Android performance test.\nActors: "+g.ActorCount+"; visible at end: "+g.RenderedActors+"\nMedian ms: "+times[90]+"\np95 ms: "+times[171]+"\n");Application.Quit();}
    IEnumerator Shot(string name){yield return new WaitForSecondsRealtime(.2f);var cam=Camera.main;var canvas=Object.FindFirstObjectByType<Canvas>();var rt=new RenderTexture(540,960,24){antiAliasing=2};cam.targetTexture=rt;cam.aspect=540f/960;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();yield return null;yield return null;ReferenceGame.Instance.RenderForCapture();cam.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var img=new Texture2D(540,960,TextureFormat.RGB24,false);img.ReadPixels(new Rect(0,0,540,960),0,0);img.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),img.EncodeToPNG());RenderTexture.active=previous;cam.targetTexture=null;canvas.renderMode=RenderMode.ScreenSpaceOverlay;Destroy(img);rt.Release();Destroy(rt);}
}
#endif
